// GhidraScript: disassemble and decompile at given addresses without relying
// on prior auto-analysis.
// Usage: -postScript DisasmAt.java <addr> [<count> ...]
// @category NSMBUDX

import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;
import ghidra.program.model.listing.Instruction;
import ghidra.program.model.listing.InstructionIterator;

public class DisasmAt extends GhidraScript {
    @Override
    public void run() throws Exception {
        String[] args = getScriptArgs();
        DecompInterface di = new DecompInterface();
        di.setOptions(new DecompileOptions());
        di.toggleCCode(true);
        di.setSimplificationStyle("decompile");
        di.openProgram(currentProgram);

        for (int i = 0; i < args.length; i++) {
            String hex = args[i].startsWith("0x") ? args[i].substring(2) : args[i];
            int count = 40;
            if (i + 1 < args.length) {
                try {
                    count = Integer.parseInt(args[i + 1]);
                    i++;
                } catch (NumberFormatException e) {
                    /* next arg is an address */
                }
            }
            long value = Long.parseLong(hex, 16);
            Address addr = currentProgram.getAddressFactory().getDefaultAddressSpace()
                    .getAddress(value);
            println("=================================================");
            println("### " + args[i - (i > 0 ? 0 : 0)] + " @ 0x" + hex);
            println("=================================================");
            ghidra.program.model.mem.MemoryBlock blk =
                    currentProgram.getMemory().getBlock(addr);
            println("  block: " + (blk == null ? "none" : blk.getName() +
                    " r=" + blk.isRead() + " w=" + blk.isWrite() + " x=" + blk.isExecute() +
                    " init=" + blk.isInitialized()));
            boolean dis = disassemble(addr);
            println("  disassemble -> " + dis);
            ghidra.program.model.listing.Instruction probe = getInstructionAt(addr);
            println("  instruction at addr: " + (probe == null ? "none" : probe.toString()));
            Function f = getFunctionAt(addr);
            if (f == null) {
                f = createFunction(addr, "fn_" + hex);
            }
            if (f == null) {
                println("  (could not create a function)");
                continue;
            }
            println("---- INSTRUCTIONS ----");
            InstructionIterator it = currentProgram.getListing().getInstructions(f.getBody(), true);
            int n = 0;
            while (it.hasNext() && n < count) {
                Instruction ins = it.next();
                println("  0x" + ins.getAddress().toString() + ":  " + ins.toString());
                n++;
            }
            println("---- PSEUDOCODE ----");
            DecompileResults res = di.decompileFunction(f, 180, monitor);
            if (res != null && res.decompileCompleted()) {
                println(res.getDecompiledFunction().getC());
            } else {
                println("(decompile failed)");
            }
        }
        di.dispose();
    }
}

DumpInfo.java.content:
// GhidraScript: summarize an imported NSO-derived ELF32 ARM image and locate
// the code that references named assets (powerups, actors, models).
// @category NSMBUDX
// @keybinding
// @menupath
// @toolbar

import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.*;
import ghidra.program.model.mem.Memory;
import ghidra.program.model.symbol.*;
import java.util.*;

public class DumpInfo extends GhidraScript {
    @Override
    public void run() throws Exception {
        println("=== IMAGE ===");
        println("language   : " + currentProgram.getLanguageID());
        println("compiler   : " + currentProgram.getCompilerSpec().getCompilerSpecID());
        println("image base : " + currentProgram.getImageBase());
        println("exec path  : " + currentProgram.getExecutablePath());

        Listing listing = currentProgram.getListing();
        Memory memory = currentProgram.getMemory();

        FunctionManager fm = currentProgram.getFunctionManager();
        println("functions  : " + fm.getFunctionCount());
        println("symbols    : " + currentProgram.getSymbolTable().getNumSymbols());

        DataIterator it = listing.getDefinedData(true);
        int strings = 0;
        List<String> wanted = Arrays.asList(
            "power_up", "SE_EMY_FIRE_BROS_FIRE", "SE_EMY_HAMMER_BROS_HAMMER",
            "bros_hammer", "bros_hammer_model", "mega_hammer", "SE_OBJ_FIREBALL_DISAPP",
            "SE_PLY_THROW_ICEBALL", "Propeller", "I_propeller_model", "P_Propeller_00",
            "bros_boomerang", "SE_EMY_BOOMERANG_BROS_BOOMERANG");
        Map<String, List<String>> hits = new LinkedHashMap<>();
        for (String w : wanted) {
            hits.put(w, new ArrayList<String>());
        }

        while (it.hasNext()) {
            Data d = it.next();
            if (d.getDataType() != null && d.getDataType().getName().toLowerCase().contains("string")) {
                strings++;
                Object val = d.getValue();
                if (val != null) {
                    String s = val.toString();
                    for (String w : wanted) {
                        if (s.contains(w)) {
                            Address a = d.getAddress();
                            StringBuilder sb = new StringBuilder();
                            Reference[] refs = getReferencesTo(a);
                            for (Reference r : refs) {
                                Function f = fm.getFunctionContaining(r.getFromAddress());
                                sb.append("0x").append(r.getFromAddress().toString());
                                sb.append(" in ");
                                sb.append(f == null ? "<no function>" : f.getName() + "@0x" +
                                          f.getEntryPoint().toString());
                                sb.append("  ");
                            }
                            hits.get(w).add("0x" + a.toString() + "  refs=" + refs.length + "  " + sb);
                        }
                    }
                }
            }
        }
        println("strings    : " + strings);

        println("=== ASSET NAME REFERENCES ===");
        for (Map.Entry<String, List<String>> e : hits.entrySet()) {
            if (e.getValue().isEmpty()) {
                continue;
            }
            println("-- " + e.getKey());
            for (String s : e.getValue()) {
                println("   " + s);
            }
        }

        println("=== IMPORTED SYMBOLS (first 40) ===");
        SymbolIterator syms = currentProgram.getSymbolTable().getSymbolIterator();
        int shown = 0;
        while (syms.hasNext() && shown < 40) {
            Symbol sym = syms.next();
            if (sym.getName().startsWith("EXTERNAL") || sym.isExternal()) {
                println("   " + sym.getName() + "  @ " + sym.getAddress());
                shown++;
            }
        }

        println("=== LARGEST FUNCTIONS ===");
        List<Function> funcs = new ArrayList<>();
        FunctionIterator fi = fm.getFunctions(true);
        while (fi.hasNext()) {
            funcs.add(fi.next());
        }
        funcs.sort((a, b) -> Long.compare(b.getBody().getNumAddresses(), a.getBody().getNumAddresses()));
        for (int i = 0; i < Math.min(12, funcs.size()); i++) {
            Function f = funcs.get(i);
            println("   " + f.getName() + " @ 0x" + f.getEntryPoint().toString() +
                    "  size=" + f.getBody().getNumAddresses());
        }
        println("=== DONE ===");
    }
}

FindIdConstant.java.content:
// GhidraScript: find every place in the module where a given actor id
// constant is materialised. Scans raw bytes (movw / movt pairs) so it works
// even on a freshly imported image with no auto-analysis.
// Usage: -postScript FindIdConstant.java <id> [<id> ...]
// @category NSMBUDX

import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;
import ghidra.program.model.mem.Memory;
import ghidra.program.model.mem.MemoryBlock;

public class FindIdConstant extends GhidraScript {
    private int u32(Address a) throws Exception {
        Memory mem = currentProgram.getMemory();
        byte[] b = new byte[4];
        mem.getBytes(a, b);
        return (b[0] & 0xFF) | ((b[1] & 0xFF) << 8) | ((b[2] & 0xFF) << 16) | ((b[3] & 0xFF) << 24);
    }

    @Override
    public void run() throws Exception {
        String[] args = getScriptArgs();
        Memory mem = currentProgram.getMemory();
        for (String arg : args) {
            long value = arg.startsWith("0x") ? Long.parseLong(arg.substring(2), 16)
                                              : Long.parseLong(arg);
            println("=========================================================");
            println("### actor id " + value + " (0x" + Long.toHexString(value) + ")");
            println("=========================================================");
            int found = 0;
            for (MemoryBlock block : mem.getBlocks()) {
                if (!block.isExecute() || !block.isInitialized()) {
                    continue;
                }
                long size = block.getSize();
                for (long off = 0; off + 8 <= size; off += 4) {
                    Address a = block.getStart().add(off);
                    int w0 = u32(a);
                    // ARM movw: 0x0300_0000 mask, imm4:imm12
                    if ((w0 & 0x0FF0F000) != 0x03000000) {
                        continue;
                    }
                    int imm4 = (w0 >>> 16) & 0xF;
                    int rd = (w0 >>> 12) & 0xF;
                    int low = (imm4 << 12) | (w0 & 0xFFF);
                    if ((low & 0xFFFF) != (value & 0xFFFF)) {
                        continue;
                    }
                    // The compiler often emits a bare movw when the high half is
                    // zero, so a matching movt is optional.
                    boolean exact = false;
                    for (int k = 1; k <= 6; k++) {
                        Address b2 = a.add(4L * k);
                        if (b2.compareTo(block.getEnd()) > 0) {
                            break;
                        }
                        int w1 = u32(b2);
                        if ((w1 & 0x0FF0F000) == 0x04000000 && ((w1 >>> 12) & 0xF) == rd) {
                            int hi = (((w1 >>> 16) & 0xF) << 12) | (w1 & 0xFFF);
                            if (((hi << 16) | low) == (int) value) {
                                exact = true;
                            }
                            break;
                        }
                    }
                    Function f = getFunctionContaining(a);
                    println("  movw r" + rd + ", #0x" + Integer.toHexString(low) +
                            (exact ? " (+movt)" : "") + "  at 0x" + a + "  in " +
                            (f == null ? "<no function>" :
                            f.getName() + " @ 0x" + f.getEntryPoint()));
                    found++;
                }
            }
            println("  (" + found + " movw/movt site(s))");
        }
    }
}

MemMap.java.content:
// GhidraScript: dump the memory map, section map and symbol state of the
// imported image so that ELF layout problems are visible without analysis.
// @category NSMBUDX

import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.*;
import ghidra.program.model.mem.*;
import ghidra.program.model.listing.*;
import ghidra.program.model.symbol.*;

public class MemMap extends GhidraScript {
    @Override
    public void run() throws Exception {
        println("language : " + currentProgram.getLanguageID());
        println("base     : " + currentProgram.getImageBase());
        println("=== MEMORY BLOCKS ===");
        Memory memory = currentProgram.getMemory();
        for (MemoryBlock b : memory.getBlocks()) {
            println("  " + b.getName() + "  " + b.getStart() + " - " + b.getEnd() +
                    "  size=0x" + Long.toHexString(b.getSize()) +
                    "  r=" + b.isRead() + " w=" + b.isWrite() + " x=" + b.isExecute() +
                    " init=" + b.isInitialized());
        }
        println("=== SYMBOLS ===");
        SymbolTable st = currentProgram.getSymbolTable();
        println("  total symbols: " + st.getNumSymbols());
        int n = 0;
        SymbolIterator it = st.getSymbolIterator();
        while (it.hasNext() && n < 10) {
            Symbol s = it.next();
            println("  " + s.getName() + " @ " + s.getAddress() + " type=" + s.getSymbolType());
            n++;
        }
        println("=== DONE ===");
    }
}

TraceAt.java.content:
// GhidraScript: for each given address, print the containing function, its
// callers (with the calling function), and the decompiled C.
// Usage: -postScript TraceAt.java <addr> [<addr> ...]
// @category NSMBUDX

import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;
import ghidra.program.model.symbol.Reference;
import ghidra.program.model.symbol.ReferenceIterator;

public class TraceAt extends GhidraScript {
    @Override
    public void run() throws Exception {
        String[] args = getScriptArgs();
        DecompInterface di = new DecompInterface();
        di.setOptions(new DecompileOptions());
        di.toggleCCode(true);
        di.setSimplificationStyle("decompile");
        di.openProgram(currentProgram);

        for (String arg : args) {
            String hex = arg.startsWith("0x") ? arg.substring(2) : arg;
            long value = Long.parseLong(hex, 16);
            Address addr = currentProgram.getAddressFactory().getDefaultAddressSpace()
                    .getAddress(value);
            Function f = getFunctionAt(addr);
            if (f == null) {
                f = getFunctionContaining(addr);
            }
            println("=========================================================");
            println("### " + arg + "  ->  " + (f == null ? "NO FUNCTION" :
                    f.getName() + " @ " + f.getEntryPoint() +
                    "  size=" + f.getBody().getNumAddresses()));
            println("=========================================================");
            if (f == null) {
                continue;
            }
            println("---- CALLERS ----");
            ReferenceIterator it = currentProgram.getReferenceManager().getReferencesTo(f.getEntryPoint());
            int n = 0;
            while (it.hasNext() && n < 40) {
                Reference r = it.next();
                Function caller = getFunctionContaining(r.getFromAddress());
                println("   from " + r.getFromAddress() + " in " +
                        (caller == null ? "<none>" : caller.getName() + " @ " + caller.getEntryPoint()));
                n++;
            }
            if (n == 0) {
                println("   (no references to the entry point)");
            }
            println("---- PSEUDOCODE ----");
            DecompileResults res = di.decompileFunction(f, 180, monitor);
            if (res != null && res.decompileCompleted()) {
                println(res.getDecompiledFunction().getC());
            } else {
                println("(decompile failed)");
            }
        }
        di.dispose();
    }
}
